    let mut dst_i: usize = 0;

    // To be more conform with upstream
    loop {
        let (v0, v1) = unsafe {
            (
                vld1q_u8(src.get_kinda_unchecked(src_i..src_i + 16).as_ptr()),
                vld1q_u8(src.get_kinda_unchecked(src_i + 16..src_i + 32).as_ptr()),
            )
        };

